const About = () => {
    return (
        <>
            <div className="story-container">
                <h1>Our Story</h1>
                <p>Welcome to Little Lemon! We are a family-owned restaurant dedicated to providing the best Italian cuisine in town.</p>
            </div>
            <div className="description-container">
                <h1>About Our Restaurant</h1>
                <p>Little Lemon is a chain of three top-rated Italian restaurants, conveniently located in New York, Boston, and Chicago. For four decades, Little  restaurant has been serving the local community with the world's famous cuisines. Our diversified menu has something special to meet any taste.</p>
                <p>Signature Mediterranean dishes;<br />
Many vegan and vegetarian options;<br />
High quality of products in all our restaurants.<br />
Our atmosphere is warm and inviting, perfect for any occasion, whether you're looking for a romantic dinner or a casual night out with friends. Come and experience the exquisite flavors of the Mediterranean with us!</p>
            </div>
        </>
    );
};

export default About;
